            return this;
        }

        ClickHouseNode newNode;
        if (config.isSsl()) {
            newNode = probe(host, port, config.getSslMode(), config.getSslRootCert(), config.getSslCert(),
                    config.getSslKey(), config.getConnectionTimeout());
        } else {
            newNode = probe(host, port, config.getConnectionTimeout());
        }
        return newNode;
    }

