@Sessional
    @Override
	protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String clientIp = request.getHeader("X-Forwarded-For");
        if (clientIp == null) clientIp = request.getRemoteAddr();

        if (!InetAddress.getByName(clientIp).isLoopbackAddress()) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN,
                    "Git hook callbacks can only be accessed from localhost.");
            return;
        }

        List<String> fields = StringUtils.splitAndTrim(request.getPathInfo(), "/");
        Preconditions.checkState(fields.size() == 2);

        Project project = projectManager.load(Long.valueOf(fields.get(0)));
        Long userId = Long.valueOf(fields.get(1));
        ThreadContext.bind(SecurityUtils.asSubject(userId));

        String refUpdateInfo = null;
        Enumeration<String> paramNames = request.getParameterNames();
        while (paramNames.hasMoreElements()) {
        	String paramName = paramNames.nextElement();
        	if (paramName.contains(" ")) {
        		refUpdateInfo = paramName;
        	} 
        }
        Preconditions.checkState(refUpdateInfo != null, "Git ref update information is not available");

		Output output = new Output(response.getOutputStream());

        /*
         * If multiple refs are updated, the hook stdin will put each ref update info into
         * a separate line, however the line breaks is omitted when forward the hook stdin
         * to curl via "@-", below logic is used to parse these info correctly even 
         * without line breaks.  
         */
        refUpdateInfo = StringUtils.reverse(StringUtils.remove(refUpdateInfo, '\n'));

        fields.clear();
        fields.addAll(StringUtils.splitAndTrim(refUpdateInfo, " "));

        List<ImmutableTriple<String, ObjectId, ObjectId>> eventData = new ArrayList<>();

        int pos = 0;
        while (true) {
        	String refName = StringUtils.reverse(fields.get(pos));
        	pos++;
        	ObjectId newObjectId = ObjectId.fromString(StringUtils.reverse(fields.get(pos)));
        	pos++;
        	String field = fields.get(pos);
        	ObjectId oldObjectId = ObjectId.fromString(StringUtils.reverse(field.substring(0, 40)));

        	String branch = GitUtils.ref2branch(refName);
        	if (branch != null && project.getDefaultBranch() == null) {
        		RefUpdate refUpdate = GitUtils.getRefUpdate(project.getRepository(), "HEAD");
        		GitUtils.linkRef(refUpdate, refName);
        	}

        	if (branch != null && project.getDefaultBranch() != null && !branch.equals(project.getDefaultBranch()))
        		showPullRequestLink(output, project, branch);

        	eventData.add(new ImmutableTriple<>(refName, oldObjectId, newObjectId));

        	field = field.substring(40);
        	if (field.length() == 0)
        		break;
        	else
        		fields.set(pos, field);
        }

        Long projectId = project.getId();

        sessionManager.runAsync(new Runnable() {

			@Override
			public void run() {
		        try {
		        	// We can not use a hibernate entity safely in a different thread. Let's reload it 
		            Project project = projectManager.load(projectId);

		            for (ImmutableTriple<String, ObjectId, ObjectId> each: eventData) {
		            	String refName = each.getLeft();
		            	ObjectId oldObjectId = each.getMiddle();
		            	ObjectId newObjectId = each.getRight();
			        	if (!newObjectId.equals(ObjectId.zeroId()))
			        		project.cacheObjectId(refName, newObjectId);
			        	else 
			        		project.cacheObjectId(refName, null);

			        	listenerRegistry.post(new RefUpdated(project, refName, oldObjectId, newObjectId));
		            }
		        } catch (Exception e) {
		        	logger.error("Error posting ref updated event", e);
				}
			}

        });
	}

private void showPullRequestLink(Output output, Project project, String branch) {
    	output.writeLine();
    	output.writeLine("Create a pull request for '"+ branch +"' by visiting:");
		output.writeLine("    " + project.getUrl() 
				+"/pulls/new?target=" 
				+ project.getId() 
				+ ":" 
				+ project.getDefaultBranch() 
				+ "&source=" 
				+ project.getId()
				+ ":"
				+ branch);
		output.writeLine();
	}

protected void processPacks(final HttpServletRequest request, final HttpServletResponse response) 
			throws ServletException, IOException, InterruptedException, ExecutionException {
		File gitDir;
		boolean upload;
		Map<String, String> environments = new HashMap<>();

		sessionManager.openSession();
		try {
			String pathInfo = getPathInfo(request);

			String service = StringUtils.substringAfterLast(pathInfo, "/");

			String projectInfo = StringUtils.substringBeforeLast(pathInfo, "/");
			Project project = getProject(request, response, projectInfo);

			doNotCache(response);
			response.setHeader("Content-Type", "application/x-" + service + "-result");			

			String serverUrl;
	        if (serverConfig.getHttpPort() != 0)
	            serverUrl = "http://localhost:" + serverConfig.getHttpPort();
	        else 
	            serverUrl = "https://localhost:" + serverConfig.getHttpsPort();

	        environments.put("ONEDEV_CURL", settingManager.getSystemSetting().getCurlConfig().getExecutable());
			environments.put("ONEDEV_URL", serverUrl);
			environments.put("ONEDEV_USER_ID", SecurityUtils.getUserId().toString());
			environments.put("ONEDEV_REPOSITORY_ID", project.getId().toString());

			// to be compatible with old repository
	        environments.put("GITPLEX_CURL", settingManager.getSystemSetting().getCurlConfig().getExecutable());
			environments.put("GITPLEX_URL", serverUrl);
			environments.put("GITPLEX_USER_ID", SecurityUtils.getUserId().toString());
			environments.put("GITPLEX_REPOSITORY_ID", project.getId().toString());

			gitDir = storageManager.getProjectGitDir(project.getId());

			if (GitSmartHttpTools.isUploadPack(request)) {
				checkPullPermission(request, project);
				upload = true;
			} else {
				if (!SecurityUtils.canWriteCode(project))
					throw new UnauthorizedException("You do not have permission to push to this project.");
				upload = false;
			}			
		} finally {
			sessionManager.closeSession();
		}

		InputStream stdin = new InputStreamWrapper(ServletUtils.getInputStream(request)) {

			@Override
			public void close() throws IOException {
			}

		};
		OutputStream stdout = new OutputStreamWrapper(response.getOutputStream()) {

			@Override
			public void close() throws IOException {
			}

		};

		String protocol = request.getHeader("Git-Protocol");		

		if (upload) {
			workExecutor.submit(new PrioritizedRunnable(PRIORITY) {

				@Override
				public void run() {
					AtomicBoolean toleratedErrors = new AtomicBoolean(false);
					ErrorCollector stderr = new ErrorCollector(StandardCharsets.UTF_8.name()) {

						@Override
						public void consume(String line) {
							super.consume(line);
							// This error may happen during a normal shallow fetch/clone 
							if (line.contains("remote end hung up unexpectedly")) {
								toleratedErrors.set(true);
								logger.debug(line);
							} else {
								logger.error(line);
							}
						}

					};

					ExecutionResult result;
					UploadPackCommand upload = new UploadPackCommand(gitDir, environments);
					upload.stdin(stdin).stdout(stdout).stderr(stderr).statelessRpc(true).protocol(protocol);
					result = upload.call();
					result.setStderr(stderr.getMessage());

					if (result.getReturnCode() != 0 && !toleratedErrors.get())
						throw result.buildException();
				}

			}).get();
		} else {
			workExecutor.submit(new PrioritizedRunnable(PRIORITY) {

				@Override
				public void run() {
					ErrorCollector stderr = new ErrorCollector(StandardCharsets.UTF_8.name()) {

						@Override
						public void consume(String line) {
							super.consume(line);
							logger.error(line);
						}

					};

					ReceivePackCommand receive = new ReceivePackCommand(gitDir, environments);
					receive.stdin(stdin).stdout(stdout).stderr(stderr).statelessRpc(true).protocol(protocol);
					ExecutionResult result = receive.call();
					result.setStderr(stderr.getMessage());
					result.checkReturnCode();
				}

			}).get();
		}
	}

private Project getProject(HttpServletRequest request, HttpServletResponse response, String projectInfo) 
			throws IOException {
		String projectPath = StringUtils.strip(projectInfo, "/");

		Project project = projectManager.findByPath(projectPath);
		if (project == null && projectPath.startsWith("projects/")) {
			projectPath = projectPath.substring("projects/".length());
			project = projectManager.findByPath(projectPath);
		}
		if (project == null) 
			throw new GitException(String.format("Unable to find project '%s'", projectPath));
		return project;
	}

